@PluginDescriptor(
		name = "Leechfin Hero",
		description = "Guitar Hero-inspired Leechfin Fishing.",
		tags = {"leechfin", "fishing", "guitar hero","vampyrium"}
)

public class LeechfinFishingPlugin extends Plugin
{
	public static final Logger log = LoggerFactory.getLogger(LeechfinFishingPlugin.class);

	// LEECHFIN HERO SCORING

	private static final String SCORE_GROUP = "leechfinfishing";
	private static final String HIGH_SCORE_KEY = "heroHighScore";
	private static final String HIGH_STREAK_KEY = "heroHighStreak";

	private long runScore = 0;
	private long highScore = 0;

	private int catchStreak = 0;
	private int highestStreak = 0;
	private int lastFishingXp = -1;

	private boolean scoreSessionActive = false;

	// manually coded ids until api updated
	// varbit used to determine if actively fishing leechfin spot
	public static final int ACTIVE_VARBIT_ID = 15454;
	// leechfin projectile and leechfin fishing spot game object ids
	public static final int LEECHFIN_ID = 3992;
	public static final int LEECHFIN_FISHING_SPOT_ID = 62193;

	private static final int CLIENT_TICKS_PER_GAME_TICK = Constants.GAME_TICK_LENGTH / Constants.CLIENT_TICK_LENGTH;
	private static final int MAX_NORTH_DISTANCE = 5 * Perspective.LOCAL_TILE_SIZE;
	private static final int MAX_X_OFFSET = 2 * Perspective.LOCAL_TILE_SIZE;

	private @Getter List<LocalPoint> leechfinFishingPoints;
	private @Getter LocalPoint closestLeechfinFishingPoint;
	private @Getter Projectile activeLeechfin;
	private @Getter LocalPoint activeLeechfinPoint;
	private @Getter Projectile nextLeechfin;
	private @Getter LocalPoint nextLeechfinPoint;

	private final Map<Projectile, Integer> fishNumbers =
			new IdentityHashMap<>();

	private int waveFishCount = 0;
	private int lastFishStartCycle = -1;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private Client client;

	@Inject
	private ConfigManager configManager;

	@Inject
	private LeechfinFishingConfig config;

	@Inject
	private LeechfinFishingOverlay overlay;

	@Inject
	private LeechfinInventoryOverlay inventoryOverlay;

	@Inject
	private LeechfinScoreOverlay scoreOverlay;

	@Override
	protected void startUp() throws Exception
	{
		String savedStreak = configManager.getConfiguration(
				SCORE_GROUP,
				HIGH_STREAK_KEY
		);

		try
		{
			highestStreak = savedStreak == null
					? 0
					: Integer.parseInt(savedStreak);
		}
		catch (NumberFormatException ex)
		{
			highestStreak = 0;
		}

		// Load the saved Leechfin Hero high score.
		String savedScore = configManager.getConfiguration(
				SCORE_GROUP,
				HIGH_SCORE_KEY
		);

		try
		{
			highScore = savedScore == null
					? 0
					: Long.parseLong(savedScore);
		}
		catch (NumberFormatException ex)
		{
			highScore = 0;
		}

		log.debug("Leechfin Fishing started!");

		overlayManager.add(overlay);
		overlayManager.add(inventoryOverlay);
		overlayManager.add(scoreOverlay);
	}

	@Override
	protected void shutDown() throws Exception
	{
		// Save the high score before closing.
		finishScoreSession();

		log.debug("Leechfin Fishing stopped!");

		overlayManager.remove(overlay);
		overlayManager.remove(inventoryOverlay);
		overlayManager.remove(scoreOverlay);
	}

	@Provides
	LeechfinFishingConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(LeechfinFishingConfig.class);
	}
	@Subscribe
	public void onGameTick(GameTick event)
	{
		// Check whether a scoring run has started or ended.
		updateScoreSession();

		WorldView worldView = client.getTopLevelWorldView();

		leechfinFishingPoints = findLeechfinFishingPoints(worldView);
		// no fishing spots found
		if (leechfinFishingPoints.isEmpty())
		{
			activeLeechfin = null;
			activeLeechfinPoint = null;
			nextLeechfin = null;
			nextLeechfinPoint = null;
			return;
		}

		closestLeechfinFishingPoint = findClosestLeechfinFishingPoint(client.getLocalPlayer());
		if (closestLeechfinFishingPoint == null)
		{
			activeLeechfin = null;
			activeLeechfinPoint = null;
			nextLeechfin = null;
			nextLeechfinPoint = null;
			return;
		}

		List<Projectile> leechfin = getSortedLeechfin();

		if (isLeechfinFishing())
		{
			trackStarPowerFish(leechfin);
		}
		else
		{
			fishNumbers.clear();
			waveFishCount = 0;
			lastFishStartCycle = -1;
		}
		// no leechfin on screen
		if (leechfin.isEmpty())
		{
			activeLeechfin = null;
			activeLeechfinPoint = null;
			nextLeechfin = null;
			nextLeechfinPoint = null;
			return;
		}

		// ensure active is still valid, set if not
		if (activeLeechfin == null || !leechfin.contains(activeLeechfin))
		{
			activeLeechfin = leechfin.get(0);
		}
		activeLeechfinPoint = findPoint(worldView, activeLeechfin);

		// now find next leechfin with a different x position
		nextLeechfin = findNextLeechfin(activeLeechfin, leechfin);
		nextLeechfinPoint = findPoint(worldView, nextLeechfin);
	}

	private List<Projectile> getSortedLeechfin()
	{
		List<Projectile> list = new ArrayList<>();
		for (Projectile leechfinProjectile : client.getProjectiles())
		{
			if (!isValidLeechfin(leechfinProjectile))
			{
				continue;
			}
			list.add(leechfinProjectile);
		}
		list.sort(Comparator.comparingDouble(Projectile::getRemainingCycles));

		return list;
	}

	private boolean isValidLeechfin(Projectile leechfinProjectile)
	{
		// if projectile is not a leechfin, don't include
		if (leechfinProjectile.getId() != LEECHFIN_ID)
		{
			return false;
		}

		LocalPoint localSourcePoint = LocalPoint.fromWorld(client, leechfinProjectile.getSourcePoint());
		if (localSourcePoint == null)
		{
			return false;
		}

		// if source is more than 5 tiles north, don't include
		if (localSourcePoint.getY() > closestLeechfinFishingPoint.dy(MAX_NORTH_DISTANCE).getY())
		{
			return false;
		}

		// if source is more 2 tiles east or west, don't include
		if (Math.abs(localSourcePoint.getX() - closestLeechfinFishingPoint.getX()) > MAX_X_OFFSET)
		{
			return false;
		}

		// if remaining cycles is less than a tick, don't include, it's too late to click
		if (leechfinProjectile.getRemainingCycles() <= CLIENT_TICKS_PER_GAME_TICK)
		{
			return false;
		}

		return true;
	}

	private Projectile findNextLeechfin(Projectile active, List<Projectile> list)
	{
		if (active == null)
		{
			return list.isEmpty() ? null : list.get(0);
		}

		int idx = list.indexOf(active);
		// if list does not contain active
		if (idx == -1)
		{
			return list.isEmpty() ? null : list.get(0);
		}
		// if active is last list index, next would be out of range, so return null
		if (idx + 1 >= list.size())
		{
			return null;
		}
		// if next has the same x as active, skip to the next after that
		if (list.get(idx).getSourcePoint().getX() == list.get(idx + 1).getSourcePoint().getX())
		{
			return findNextLeechfin(list.get(idx + 1), list);
		}

		return list.get(idx + 1);
	}

	public static boolean isInventoryFull(Client client)
	{
		ItemContainer inventory = client.getItemContainer(InventoryID.INV);
		return inventory != null && inventory.size() <= inventory.count();
	}

	public boolean isLeechfinFishing()
	{
		return client.getVarbitValue(LeechfinFishingPlugin.ACTIVE_VARBIT_ID) == 1;
	}

	private LocalPoint findPoint(WorldView worldView, Projectile projectile)
	{
		if (projectile == null)
		{
			return null;
		}

		int x = (int) projectile.getX();
		int y = (int) projectile.getY();

		return new LocalPoint(x, y, worldView);
	}

	private LocalPoint findClosestLeechfinFishingPoint(Player player)
	{
		if (player == null || leechfinFishingPoints.isEmpty())
		{
			return null;
		}

		// have to compare LocalPoint with LocalPoint, so use getLocalLocation
		LocalPoint playerLocation = player.getLocalLocation();

		return leechfinFishingPoints.stream()
			.min(Comparator.comparingInt(
				spot -> spot.distanceTo(playerLocation)
			))
			.orElse(null);
	}

	private List<LocalPoint> findLeechfinFishingPoints(WorldView worldview)
	{
		List<LocalPoint> leechfinFishingSpots = new ArrayList<>();

		Tile[][][] tiles = worldview.getScene().getTiles();
		int z = worldview.getPlane();

		for (int x = 0; x < tiles[z].length; ++x)
		{
			for (int y = 0; y < tiles[z][x].length; ++y)
			{
				Tile tile = tiles[z][x][y];
				if (tile == null)
				{
					continue;
				}

				GameObject[] gameObjects = tile.getGameObjects();
				for (GameObject gameObject : gameObjects)
				{
					if (gameObject != null && gameObject.getId() == LEECHFIN_FISHING_SPOT_ID)
					{
						leechfinFishingSpots.add(gameObject.getLocalLocation());
					}
				}
			}
		}

		return leechfinFishingSpots;
	}

	private void trackStarPowerFish(List<Projectile> fish)
	{
		// Remove fish that have disappeared.
		List<Projectile> present = new ArrayList<>();

		for (Projectile p : client.getProjectiles())
		{
			if (p.getId() == LEECHFIN_ID)
			{
				present.add(p);
			}
		}

		fishNumbers.keySet().retainAll(present);

		// Identify newly spawned fish.
		List<Projectile> newFish = new ArrayList<>();

		for (Projectile p : fish)
		{
			if (!fishNumbers.containsKey(p))
			{
				newFish.add(p);
			}
		}

		// Process them in spawning order.
		newFish.sort(Comparator.comparingInt(Projectile::getStartCycle));

		for (Projectile p : newFish)
		{
			int startCycle = p.getStartCycle();

			// A gap indicates a new wave.
			if (lastFishStartCycle >= 0 &&
					startCycle - lastFishStartCycle > CLIENT_TICKS_PER_GAME_TICK * 2)
			{
				waveFishCount = 0;
			}

			waveFishCount = (waveFishCount % 22) + 1;

			fishNumbers.put(p, waveFishCount);
			lastFishStartCycle = startCycle;
		}
	}

	public boolean isStarPowerFish(Projectile fish)
	{
		Integer number = fishNumbers.get(fish);

		return number != null && number >= 10 && number <= 14;
	}

	private void updateScoreSession()
	{
		boolean fishing = isLeechfinFishing();

		// Player has started actively fishing.
		if (fishing && !scoreSessionActive)
		{
			scoreSessionActive = true;

			// Start a fresh run.
			runScore = 0;
			catchStreak = 0;

			lastFishingXp =
					client.getSkillExperience(Skill.FISHING);
		}

		// Player is no longer actively fishing.
		else if (!fishing && scoreSessionActive)
		{
			finishScoreSession();
		}
	}

	private void finishScoreSession()
	{
		if (!scoreSessionActive)
		{
			return;
		}

		// Save personal best.
		if (runScore > highScore)
		{
			highScore = runScore;

			configManager.setConfiguration(
					SCORE_GROUP,
					HIGH_SCORE_KEY,
					highScore
			);
		}

		// End the run.
		scoreSessionActive = false;
		catchStreak = 0;
	}



	@Subscribe
	public void onStatChanged(StatChanged event)
	{
		// We only care about Fishing experience.
		if (event.getSkill() != Skill.FISHING)
		{
			return;
		}

		int currentXp = event.getXp();

		// Establish baseline if necessary.
		if (lastFishingXp < 0)
		{
			lastFishingXp = currentXp;
			return;
		}

		// Calculate actual XP received.
		int xpGained = currentXp - lastFishingXp;

		lastFishingXp = currentXp;

		// Don't award points outside a fishing session.
		if (!scoreSessionActive || xpGained <= 0)
		{
			return;
		}

		// Every fish that awards XP counts toward the streak,
		// including failed catches (3 XP).
		catchStreak++;

// Update personal best streak.
		if (catchStreak > highestStreak)
		{
			highestStreak = catchStreak;

			configManager.setConfiguration(
					SCORE_GROUP,
					HIGH_STREAK_KEY,
					highestStreak
			);
		}

		runScore += (long) xpGained * getScoreMultiplier();
	}


// METHODS USED BY THE SCORE OVERLAY

	public int getScoreMultiplier()
	{
		if (catchStreak >= 30)
		{
			return 4;
		}
		if (catchStreak >= 21)
		{
			return 3;
		}
		if (catchStreak >= 11)
		{
			return 2;
		}

		return 1;
	}

	public int getCatchStreak()
	{
		return catchStreak;
	}

	public int getHighestStreak()
	{
		return highestStreak;
	}

	public long getRunScore()
	{
		return runScore;
	}

	public long getHeroHighScore()
	{
		// Display a new personal best immediately,
		// even before the session finishes.
		return Math.max(highScore, runScore);
	}

	public boolean isScoreSessionActive()
	{
		return scoreSessionActive;
	}
	public void breakCatchStreak()
	{
		if (scoreSessionActive)
		{
			catchStreak = 0;
		}
	}


	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (!SCORE_GROUP.equals(event.getGroup()))
		{
			return;
		}

		// Only process actual checkbox values.
		if (!"true".equals(event.getNewValue()) &&
				!"false".equals(event.getNewValue()))
		{
			return;
		}

		// RESET STREAKS
		if ("resetStreaks".equals(event.getKey()))
		{
			catchStreak = 0;
			highestStreak = 0;

			configManager.setConfiguration(
					SCORE_GROUP,
					HIGH_STREAK_KEY,
					0
			);

		}

		// RESET HIGH SCORE
		else if ("resetHighScore".equals(event.getKey()))
		{
			highScore = 0;

			configManager.setConfiguration(
					SCORE_GROUP,
					HIGH_SCORE_KEY,
					0
			);

		}
	}



}

package com.leechfinfishing;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.Stroke;
import javax.inject.Inject;

import net.runelite.api.widgets.WidgetItem;
import net.runelite.client.ui.overlay.WidgetItemOverlay;

public class LeechfinInventoryOverlay extends WidgetItemOverlay
{
    private static final int LEECHFIN_ITEM_ID = 33621;

    private final LeechfinFishingPlugin plugin;

    @Inject
    public LeechfinInventoryOverlay(LeechfinFishingPlugin plugin)
    {
        this.plugin = plugin;
        showOnInventory();
    }

    @Override
    public void renderItemOverlay(
            Graphics2D graphics,
            int itemId,
            WidgetItem widgetItem)
    {
        // Only highlight actual leechfin inventory items.
        if (itemId != LEECHFIN_ITEM_ID)
        {
            return;
        }

        // Only highlight during fishing, while fish 10-14 are active.
        if (!plugin.isLeechfinFishing() ||
                !plugin.isStarPowerFish(plugin.getActiveLeechfin()))
        {
            return;
        }


        Rectangle bounds = widgetItem.getCanvasBounds();

        if (bounds == null)
        {
            return;
        }

// STAR POWER PULSE
// 600 milliseconds = approximately one OSRS game tick.
        long pulsePeriod = 600_000_000L;

        double phase = (System.nanoTime() % pulsePeriod)
                / (double) pulsePeriod;

// Smoothly oscillates between 0 and 1.
        double pulse = (Math.sin(2 * Math.PI * phase) + 1) / 2;

// Calculate the changing brightness and thickness.
        int fillAlpha = (int) (25 + pulse * 110);
        int borderAlpha = (int) (110 + pulse * 145);
        float borderWidth = 1.5f + (float) (pulse * 2.0);

        Stroke previousStroke = graphics.getStroke();

// Soft outer glow.
        graphics.setColor(new Color(
                0, 255, 255, (int) (15 + pulse * 45)
        ));

        graphics.setStroke(new BasicStroke(borderWidth + 4));

        graphics.drawRoundRect(
                bounds.x - 2,
                bounds.y - 2,
                bounds.width + 3,
                bounds.height + 3,
                8, 8
        );

// Pulsing translucent fill.
        graphics.setColor(new Color(0, 255, 255, fillAlpha));

        graphics.fillRoundRect(
                bounds.x,
                bounds.y,
                bounds.width,
                bounds.height,
                6, 6
        );

// Pulsing cyan border.
        graphics.setColor(new Color(0, 255, 255, borderAlpha));
        graphics.setStroke(new BasicStroke(borderWidth));

        graphics.drawRoundRect(
                bounds.x,
                bounds.y,
                bounds.width - 1,
                bounds.height - 1,
                6, 6
        );

// Restore original graphics settings.
        graphics.setStroke(previousStroke);

    }
}

package com.leechfinfishing;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import javax.inject.Inject;

import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.components.LineComponent;

public class LeechfinScoreOverlay extends OverlayPanel
{
    private final LeechfinFishingPlugin plugin;

    @Inject
    public LeechfinScoreOverlay(LeechfinFishingPlugin plugin)
    {
        this.plugin = plugin;

        setPosition(OverlayPosition.TOP_LEFT);
        setLayer(OverlayLayer.ABOVE_WIDGETS);

        panelComponent.setPreferredSize(new Dimension(150, 0));
    }

    @Override
    public Dimension render(Graphics2D graphics)
    {
        // Only display while fishing or near the fishing spot.
        if (!plugin.isScoreSessionActive()
                && (plugin.getLeechfinFishingPoints() == null
                || plugin.getLeechfinFishingPoints().isEmpty()))
        {
            return null;
        }

        int multiplier = plugin.getScoreMultiplier();

        Color multiplierColor = Color.WHITE;

        if (multiplier == 2)
        {
            multiplierColor = Color.YELLOW;
        }
        else if (multiplier == 3)
        {
            multiplierColor = Color.ORANGE;
        }
        else if (multiplier == 4)
        {
            multiplierColor = Color.CYAN;
        }

        // HEADER
        panelComponent.getChildren().add(
                LineComponent.builder()
                        .left("LEECHFIN HERO")
                        .leftColor(Color.CYAN)
                        .build()
        );

        // CURRENT SCORE
        panelComponent.getChildren().add(
                LineComponent.builder()
                        .left("Score")
                        .right(String.format("%,d", plugin.getRunScore()))
                        .build()
        );

        // CURRENT STREAK
        panelComponent.getChildren().add(
                LineComponent.builder()
                        .left("Note Streak")
                        .right(String.valueOf(plugin.getCatchStreak()))
                        .build()
        );

        // MULTIPLIER
        panelComponent.getChildren().add(
                LineComponent.builder()
                        .left("Multiplier")
                        .right("x" + multiplier)
                        .rightColor(multiplierColor)
                        .build()
        );

        // Divider between current stats and personal records
        panelComponent.getChildren().add(
                LineComponent.builder()
                        .left("─────────────")
                        .leftColor(Color.GRAY)
                        .build()
        );

        // HIGHEST STREAK
        panelComponent.getChildren().add(
                LineComponent.builder()
                        .left("Highest Streak")
                        .right(String.valueOf(plugin.getHighestStreak()))
                        .rightColor(Color.YELLOW)
                        .build()
        );

        // PERSONAL BEST
        panelComponent.getChildren().add(
                LineComponent.builder()
                        .left("High Score")
                        .right(String.format("%,d",
                                plugin.getHeroHighScore()))
                        .rightColor(Color.YELLOW)
                        .build()
        );

        return super.render(graphics);
    }
}

